using Ebm.Domain.Common;
using Microsoft.EntityFrameworkCore;

namespace Ebm.Persistence;

/// <summary>
/// EF Core context of the game database. Entity mappings live in <c>Configurations/</c>.
/// </summary>
/// <remarks>
/// Conventions applied to every entity: strongly typed IDs are stored as GUIDs, keys are assigned by the
/// domain (never generated by the database), and deleting a referenced record is refused (no cascade),
/// so history is never removed as a side effect.
/// </remarks>
public sealed class EbmDbContext : DbContext
{
    public EbmDbContext(DbContextOptions<EbmDbContext> options)
        : base(options)
    {
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        ArgumentNullException.ThrowIfNull(configurationBuilder);

        foreach (var idType in EntityIdTypes())
        {
            configurationBuilder.Properties(idType).HaveConversion(typeof(EntityIdConverter<>).MakeGenericType(idType));
        }
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        ArgumentNullException.ThrowIfNull(modelBuilder);

        modelBuilder.ApplyConfigurationsFromAssembly(typeof(EbmDbContext).Assembly);

        foreach (var entityType in modelBuilder.Model.GetEntityTypes().Where(t => !t.IsOwned()))
        {
            foreach (var key in entityType.GetKeys().Where(k => k.IsPrimaryKey()).SelectMany(k => k.Properties))
            {
                key.ValueGenerated = Microsoft.EntityFrameworkCore.Metadata.ValueGenerated.Never;
            }

            foreach (var foreignKey in entityType.GetForeignKeys())
            {
                foreignKey.DeleteBehavior = DeleteBehavior.Restrict;
            }
        }
    }

    private static IEnumerable<Type> EntityIdTypes() =>
        typeof(IEntityId<>).Assembly.GetTypes().Where(t =>
            t is { IsValueType: true, IsAbstract: false }
            && t.GetInterfaces().Any(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IEntityId<>)));
}
